    "ward.qm-no-due-times": "ఈ వ్యవధిలో ఇచ్చిన {given} డోస్‌లలో ఏదీ ఎప్పుడు ఇవ్వాలో రికార్డ్ చేయలేదు, కాబట్టి ఆలస్యాన్ని లెక్కించలేము. 2026-09-07 కంటే ముందు రాసిన అడ్మినిస్ట్రేషన్ రికార్డులలో dueAt లేదు.",
    "ward.qm-no-allergy-status-record": "WardSynQ \"అడిగారు, కానీ ఏమీ లేవు\" అని రికార్డ్ చేయలేదు, కాబట్టి అలెర్జీ రికార్డు లేని రోగిని, ఎవరూ అడగని రోగితో వేరు చేయడం సాధ్యపడదు. ఇక్కడ ఏ రేటు అయినా, అస్సలు అడగని వార్డు కోసం మంచి డాక్యుమెంటేషన్‌ను నివేదిస్తుంది. దీనికి లెక్కించడం కాదు, అలెర్జీలు ఏమీ లేవు (no-known-allergies) అనే రికార్డ్ అవసరం.",
