    "site.admin.staff.roleNote.admin": "పూర్తి సాంకేతిక పరిపాలన: సిబ్బంది, వార్డులు, బెడ్‌లు, విభాగాలు, గదులు, బిల్లింగ్ కాన్ఫిగ్. క్లినికల్ ప్రోటోకాల్ సంతకం లేదు.",
