    "site.admin.staff.roleNote.reception": "రోగులను నమోదు చేస్తుంది మరియు చెక్ ఇన్ చేస్తుంది, డాక్టర్‌కు కేటాయిస్తుంది. చార్ట్‌ను చదవగలరు, సవరించడం వీలు కాదు.",
    "site.admin.staff.roleNote.pharmacy": "మందుల ఆర్డర్‌లను చదువుతుంది మరియు అందిస్తుంది, చార్ట్‌తో ఆర్డర్‌ను సరిచూస్తుంది. కన్సల్టేషన్ నోట్స్ లేవు.",
    "site.admin.staff.roleNote.lab": "ఆర్డర్ చేసిన పరీక్షలను చూస్తుంది మరియు ఫలితాలను విడుదల చేస్తుంది. ఇతర చార్ట్ యాక్సెస్ లేదు.",
    "site.admin.staff.roleNote.billing": "ఛార్జీలు, ఇన్‌వాయిస్‌లు మరియు క్లెయిమ్‌లను చదువుతుంది. చెల్లింపును తీసుకోలేదు (దాని కోసం క్యాషియర్‌ను చూడండి).",
    "site.admin.staff.roleNote.him": "సమాచార విడుదల అభ్యర్థనలను నిర్ణయించడానికి మరియు నమోదు చేయడానికి చార్ట్‌ను చదువుతుంది.",
    "site.admin.staff.roleNote.bloodBank": "క్రాస్‌మ్యాచ్ చేస్తుంది, రక్తం ఇస్తుంది మరియు ట్రాన్స్‌ఫ్యూజన్‌లను మాత్రమే నిర్వహిస్తుంది.",
    "site.admin.staff.roleNote.radiographer": "ఇమేజింగ్ అధ్యయనాన్ని పొందుతుంది. చార్ట్‌ను చదవగలరు, నివేదికను ఫైల్ చేయడం లేదా అధ్యయనాన్ని ప్రోటోకాల్ చేయడం వీలు కాదు.",
    "site.admin.staff.roleNote.radiologist": "ఇమేజింగ్ అధ్యయనాలను ప్రోటోకాల్ చేస్తుంది మరియు నివేదిస్తుంది (లాబ్ ఫలిత విడుదల ఉపయోగించే అదే అధికారం). ఇతర చార్ట్ రైట్ లేదు.",
    "site.admin.staff.roleNote.obstetrician": "PCPNDT Form F మరియు MTP రిజిస్టర్‌ను కూడా నిర్వహించే డాక్టర్.",
    "site.admin.staff.roleNote.publicHealth": "పబ్లిక్ హెల్త్ నోడల్ ఆఫీసర్: చార్ట్‌ను చదివి, నోటిఫై చేయదగిన వ్యాధుల రిజిస్టర్ మరియు వారపు IHIP ఎక్స్‌పోర్ట్‌ను నిర్వహిస్తారు.",
    "site.admin.staff.roleNote.supervisor": "OPD క్యూను నిర్వహిస్తారు మరియు చార్ట్‌ను చదువుతారు. వారి పరిధిలోని డిపార్ట్‌మెంట్‌ల స్టోర్స్ ఇండెంట్లను ఆమోదిస్తారు.",
    "site.admin.staff.roleNote.storeKeeper": "జనరల్ స్టోర్‌లను నిర్వహిస్తారు: వస్తువులు, స్టోర్ స్థానాలు, ఆమోదించిన ఇండెంట్‌లను జారీ చేయడం, స్వీకరించడం మరియు ఆర్డర్ చేయడం. Chart యాక్సెస్ లేదు.",
