    "site.admin.hospital.printLang.intro": "ఇంగ్లీష్ ప్రింట్ ఎల్లప్పుడూ నిండి ఉంటుంది మరియు ప్రామాణికమైనది. రెండవ భాష దాని పక్కన ప్రింట్ చేయబడుతుంది, అనువాదంగా గుర్తించబడుతుంది మరియు కేవలం శీర్షికలు, లేబుళ్లు మరియు ప్రిస్కైబర్ స్థిర జాబితా నుండి ఎంచుకున్న పేషెంట్ సూచనలను మాత్రమే కవర్ చేస్తుంది. మందుల పేర్లు, మోతాదులు, పౌనఃపున్యాలు, రోగనిర్ధారణలు, ఫలితాలు మరియు టైప్ చేసిన ఏదైనా ఇంగ్లీష్‌లోనే ముద్రించబడతాయి. ఇంకా రాయని అనువాదాలు ఇంగ్లీష్‌లోనే కనిపిస్తాయి (లేదు).",
    "site.admin.hospital.printLang.savedOn": "సేవ్ చేయబడింది. ప్రింట్‌లు రెండవ భాషను సదుపాయం చేస్తాయి.",
