    "site.admin.maik.note": "MaiKని ప్రారంభించడం వల్ల పైన పేర్కొన్న ప్రొవైడర్‌లు ఉపయోగించబడతారు. ఎన్విరాన్మెంట్‌లో దాని కీ (క్రెడెన్షియల్ కింద పేరు పెట్టబడినది) ఉన్నప్పుడు మాత్రమే క్లౌడ్ ప్రొవైడర్ స్పందిస్తుంది. రెండవ స్విచ్ ఆన్ చేసినప్పుడు మాత్రమే పేషెంట్ డేటా ఆసుపత్రి నుండి బయటకు వెళ్తుంది. MaiK నుండి క్లినికల్ కంటెంట్ సంతకం చేయబడలేదు.",
