    "site.admin.security.reasonGiven": "ఇచ్చిన కారణం:",
    "site.admin.security.ackArchiveNote": "ఈ అంగీకారానికి ముందు ఉన్న యాంకర్ లాగ్ ఆర్కైవ్‌గా ఉంచబడుతుంది మరియు ఎప్పుడూ తొలగించబడదు. ఈ పాయింట్ తర్వాత కొత్త తేడా ఉంటే మళ్లీ నివేదించబడుతుంది.",
    "site.admin.security.ackFormTitleOrg": "ఆసుపత్రి ఈవెంట్ లాగ్ యొక్క చట్టబద్ధమైన పునరుద్ధరణను అంగీకరించండి",
    "site.admin.security.ackFormTitle": "చట్టబద్ధమైన పునరుద్ధరణను అంగీకరించండి",
    "site.admin.security.ackFormIntro": "ఇది ప్రస్తుత బయటి కాపీని ఆర్కైవ్ చేస్తుంది మరియు తాజా వరుస నుండి మళ్లీ ప్రారంభిస్తుంది, మరియు మీ పేరు మీద ఆడిట్ ట్రయిల్‌లో అంగీకారాన్ని నమోదు చేస్తుంది. పునరుద్ధరణ ప్రణాళిక చేయబడి, క్రింది ఇన్సిడెంట్ రెఫరెన్స్ కింద వ్రాయబడినప్పుడు మాత్రమే ఇలా చేయండి. కారణంలో రోగి వివరాలను ఎప్పుడూ ఉంచవద్దు.",
