    "site.admin.security.integrityNote": "ప్రతి ఆడిట్ వరుస హాష్ ద్వారా దానికి ముందు ఉన్న దానికి లింక్ చేయబడుతుంది, కాబట్టి డేటాబేస్‌లోనే చేసిన మార్పు లేదా తొలగింపు ఇక్కడ కనిపిస్తుంది. ప్రతిసారీ తాజా వరుసలు తనిఖీ చేయబడతాయి. గంటకు ఒకసారి తాజా వరుస సంఖ్య డేటాబేస్ వెలుపల ఉన్న రెండు స్టోర్‌లకు (KV మరియు Firestore) కాపీ చేయబడి ఇక్కడ పోల్చబడుతుంది, మరియు ఆ రెండు కాపీలు ఒకదానితో ఒకటి పోల్చబడతాయి. ఇది స్విచ్ ఆన్ చేయడానికి ముందు వ్రాయబడిన వరుసలు లింక్ చేయబడలేదు మరియు తనిఖీ చేయడం రాదు.",
