    "site.admin.smart.intro2": "రిజిస్ట్రేషన్ అనేది అలౌలిస్ట్: ఇక్కడ పేరు లేని యాప్‌కు ఏదీ లభించదు, మరియు ఒకదాన్ని తొలగించడం ద్వారా దాని టోకెన్‌లు వెంటనే నిలిచిపోతాయి. స్విచ్ ఆఫ్ చేయడం వలన ప్రతి యాప్‌కు SMART ద్వారం మూసివేయబడుతుంది (లేదు).",
