    "site.maik.governedNote": "MaiK రికార్డ్ నుండి ముసాయిదా తయారుచేస్తుంది మరియు ఒక వైద్యుడు వాటిని అంగీకరించే వరకు దాని సమాధానాలు సంతకం చేయబడవు. ప్రతి ప్రతిస్పందన దాని మోడల్, మూలాలు మరియు మీ సమీక్షతో రికార్డ్‌కు వ్రాయబడుతుంది. ఈ బిల్డ్‌లోని క్లినికల్ కంటెంట్ ఇంకా ఆసుపత్రి కమిటీచే ఆమోదించబడలేదు.",
